   Func<CustomStrategyDefinition> persist=()=>{if(persisted==null){var definition=draft();CustomStrategies.Save(zapret.DirectoryPath,definition,catalog);persisted=definition;saved=CustomStrategies.Read(zapret.DirectoryPath);int previous=basis.SelectedIndex;catalog=ZapretCatalog.Load(zapret.DirectoryPath).Where(c=>c.Available&&!String.IsNullOrWhiteSpace(c.Tcp)).ToArray();syncing=true;basis.SetItems(catalog.Select(c=>c.Name));basis.SelectedIndex=previous;syncing=false;}status.Text="Сохранено: "+persisted.Name+". Доступно в общем каталоге стратегий; пока не проверено.";return persisted;};
   save.Click+=(s,e)=>{try{persist();}catch(Exception ex){GlassNotice.Show(this,ex.Message,"Копия не сохранена");}};
   test.Click+=async(s,e)=>{if(busy)return;if(connecting||setupCancellation!=null||zapretCancellation!=null||byetubeCancellation!=null||warpCancellation!=null||discordVoiceChecking){Toast("Дождитесь завершения текущей операции");return;}busy=true;parameterPanel.Enabled=false;bat.Enabled=full.Enabled=save.Enabled=test.Enabled=basis.Enabled=name.Enabled=false;foreach(var field in fields)field.Item3.Enabled=false;
    try{var chosen=services.SelectedIndices.Select(i=>checks[i]).ToArray();if(chosen.Length==0)throw new InvalidOperationException("Выберите сервисы для проверки");if(!IsAdministrator())throw new InvalidOperationException("Для проверки перезапустите MCRF от имени администратора");if(!await OfferStopTun()||!await OfferStopZapret())return;
     foreach(var field in fields){string recipe=field.Item1?catalog[basis.SelectedIndex].Tcp:catalog[basis.SelectedIndex].Udp;field.Item3.Enabled=!String.IsNullOrWhiteSpace(recipe)&&((field.Item2!="ttl"&&field.Item2!="split-pos")||Regex.IsMatch(recipe,"--dpi-desync-"+field.Item2+"="));}
     var definition=persist();foreach(var field in fields)field.Item3.Enabled=false;cancellation=new CancellationTokenSource();zapretCancellation=cancellation;var settings=new ZapretSettings{ScopeText=String.Join("\n",chosen.Select(c=>c.Domains)),MatchMode="addresses",TestUrls=String.Join("\n",chosen.SelectMany(c=>c.Urls)),CheckServices=chosen.Select(c=>c.Id).ToList(),ExcludedApplications=ApplicationExclusions.Normalize(state.ExcludedApplications).ToList()};var report=new ZapretCheckReport{Settings=settings,ServiceIds=settings.CheckServices};var live=OpenLiveResults(report,"Проверка копии стратегии",cancellation);
     try{await zapret.Scan(report,new[]{CustomStrategies.Build(definition,catalog)},cancellation.Token,message=>{WriteLog(message);if(!status.IsDisposed)status.Text=message;},value=>PersistZapretReport(value));}finally{live.Finish();}zapretReport=report;reportLoaded=true;if(!box.IsDisposed){results.Enabled=true;status.Text="Проверка завершена. Результаты сохранены; ничего не применено.";}
    }catch(OperationCanceledException){if(!box.IsDisposed)status.Text="Проверка остановлена; копия сохранена, маршруты не изменены.";}catch(Exception ex){if(!box.IsDisposed)GlassNotice.Show(this,ex.Message,"Проверка копии");}
    finally{if(zapretCancellation==cancellation)zapretCancellation=null;if(cancellation!=null){cancellation.Dispose();cancellation=null;}busy=false;if(!box.IsDisposed){parameterPanel.Enabled=true;bat.Enabled=full.Enabled=save.Enabled=test.Enabled=basis.Enabled=name.Enabled=true;foreach(var field in fields){string recipe=field.Item1?catalog[basis.SelectedIndex].Tcp:catalog[basis.SelectedIndex].Udp;field.Item3.Enabled=!String.IsNullOrWhiteSpace(recipe);}}}
   };
   box.Disposed+=(s,e)=>{if(cancellation!=null)cancellation.Cancel();};basis.SelectedIndex=Math.Max(0,Array.FindIndex(catalog,c=>c.Id==state.Zapret.Strategy));scroll.WireWheel(canvas);engineHelp=await helpLoading;if(!box.IsDisposed){refreshParameters();showHelp();}
  }
 }
